export const getLevel1Shortcuts = (): Record<string, string> => level1Shortcuts;

export const getWubiData = (): WubiCharacter[] => wubiData;

export const getLevel1Characters = (): WubiCharacter[] => 
  wubiData.filter(item => item.level === 1);

export const getLevel2Characters = (): WubiCharacter[] => 
  wubiData.filter(item => item.level === 2);

export const getCharactersByChar = (char: string, version?: WubiVersion): WubiCharacter[] => {
  let results = wubiData.filter(item => item.char === char);
  if (version) {
    results = results.filter(item => item.version === version);
  }
  results.sort((a, b) => {
    const versionOrder: Record<WubiVersion, number> = { '86': 0, '98': 1, '新世纪': 2 };
    return versionOrder[a.version] - versionOrder[b.version];
  });
  return results;
};

export const getCharactersByCode = (code: string, version?: WubiVersion): WubiCharacter[] => {
  let results = wubiData.filter(item => item.code.toUpperCase().startsWith(code.toUpperCase()));
  if (version) {
    results = results.filter(item => item.version === version);
  }
  return results;
};

export const getAllCharacters = (): WubiCharacter[] => [...wubiData];

export const getCharactersSortedByCode = (version?: WubiVersion): WubiCharacter[] => {
  let results = [...wubiData];
  if (version) {
    results = results.filter(item => item.version === version);
  }
  return results.sort((a, b) => a.code.localeCompare(b.code));
};

export interface QueryOptions {
  code: string;
  commonOnly?: boolean;
  sortBy?: 'frequency' | 'code';
  version?: WubiVersion | 'all';
}

export const getCharactersByCodeAdvanced = (options: QueryOptions): WubiCharacter[] => {
  const { code, commonOnly = false, sortBy = 'frequency', version = 'all' } = options;
  const upperCode = code.toUpperCase();
  
  let results = wubiData.filter(item => 
    item.code.toUpperCase().startsWith(upperCode)
  );
  
  if (version !== 'all') {
    results = results.filter(item => item.version === version);
  }
  
  if (commonOnly) {
    results = results.filter(item => item.level <= 3);
  }
  
  if (sortBy === 'frequency') {
    results.sort((a, b) => b.frequency - a.frequency);
  } else {
    results.sort((a, b) => a.code.localeCompare(b.code));
  }
  
  return results;
};
